'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=n=>new Intl.NumberFormat('pt-BR').format(n??0), pct=n=>n==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2,minimumFractionDigits:1}).format(n)+'%';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR'), monthLabel=m=>new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'2-digit'}).replace('.','');
const state={view:'overview',period:'',modality:'all',path:[],metric:'activeContracts',query:'',sort:'activeContracts',descending:true,month:null,marketRule:'all',marketQuery:'',marketSort:'industry',marketDescending:true};
let snapshots=(window.DASHBOARD_DATA||[]).sort((a,b)=>a.date.localeCompare(b.date));
const tips={students:'Pessoas distintas por CPF; RA é usado apenas quando não há CPF. Matrículas repetidas da mesma pessoa não aumentam este indicador.',records:'Registros de matrícula do curso com status Matriculado. Uma pessoa pode ter mais de uma matrícula.',activeContracts:'Vínculos distintos por pessoa, CNPJ e datas de início/fim. Exige CNPJ consistente, início até a data-base e término igual ou posterior à data-base.',companies:'CNPJs distintos dos vínculos vigentes. CNPJ vazio, zero ou inconsistente não conta como empresa. O total estadual não é a soma das regiões.',noContractStudents:'Pessoas com registros sem CNPJ. A mesma pessoa pode possuir outro registro com vínculo vigente.',exclusiveNoContractStudents:'Pessoas com matrícula sem CNPJ e sem qualquer vínculo vigente identificado no recorte selecionado. Requer conferência operacional antes de definir meta de formalização.',coverage:'Pessoas com ao menos um vínculo vigente ÷ pessoas matriculadas distintas. Mede cobertura contratual da carteira, não participação de mercado.',market:'Vínculos vigentes na data da carteira ÷ estoque CAGED da referência indicada. Com meses diferentes, mede uma razão de referência, não uma participação contemporânea. Não é calculado sem denominador territorial correspondente.',months:'Vencimentos dos vínculos vigentes nesta fotografia. São términos previstos, não perdas realizadas. Cada mês usa vínculos distintos.'};
function info(k){const names={students:'pessoas matriculadas',records:'registros de matrícula',activeContracts:'vínculos vigentes',companies:'empresas ativas',coverage:'cobertura contratual',market:'market share',months:'vencimentos',exclusiveNoContractStudents:'pessoas com matrícula sem CNPJ e sem vínculo vigente'};return `<button class="info" aria-label="Como calculamos ${esc(names[k]||k)}" data-tip="${esc(tips[k]||k)}">i</button>`}
function snapshot(){return snapshots.find(s=>s.date===state.period)||snapshots.at(-1)}
function root(){return snapshot().slices[state.modality]}
function node(){let n=root();for(const id of state.path){const next=n.children.find(c=>c.id===id);if(!next)break;n=next}return n}
function compatibleMarket(n){return state.modality==='all'&&n.market&&(n.market.competence===snapshot().date.slice(0,7)||n.market.referenceMode==='latest_available')?n.market:null}
function marketRate(n){const m=compatibleMarket(n);return m&&m.caged>0?n.metrics.activeContracts/m.caged*100:null}
function coverage(n){return n.metrics.students?n.metrics.activeStudents/n.metrics.students*100:null}
const metricNames={activeContracts:'Vínculos vigentes',students:'Pessoas matriculadas',exclusiveNoContractStudents:'Sem CNPJ e sem vínculo vigente',companies:'Empresas ativas'};
function card(label,value,note,key,accent=false){return `<article class="card ${accent?'accent':''}"><div class="card-label">${label} ${key?info(key):''}</div><div class="card-value ${String(value).length>12?'small-value':''}">${value}</div><div class="card-note">${note}</div></article>`}
function cards(n){const m=n.metrics;return `<section class="cards" aria-label="Indicadores do recorte">${card('Pessoas matriculadas',fmt(m.students),`${fmt(m.records)} registros de matrícula`,'students',true)}${card('Vínculos vigentes',fmt(m.activeContracts),`${fmt(m.activeStudents)} pessoas com vínculo`,'activeContracts')}${card('Empresas ativas',fmt(m.companies),'CNPJs distintos · sem código zero','companies')}${card('Cobertura contratual',pct(coverage(n)),`${fmt(m.exclusiveNoContractStudents)} pessoas a conferir`,'coverage')}</section>`}
function marketNotice(n){const m=compatibleMarket(n),rate=marketRate(n);if(rate==null)return `<div class="notice"><span class="symbol">◎</span><div><strong>Mercado disponível na visão estadual, todas as modalidades.</strong> Este recorte não possui denominador territorial ou de modalidade correspondente. Consulte <button class="text-button" data-go="market">Mercado e regras municipais ↗</button>.</div></div>`;return `<div class="notice"><span class="symbol">◎</span><div><strong>Carteira de ${date(snapshot().date)} · mercado de ${monthLabel(m.competence)}.</strong> ${m.competence!==snapshot().date.slice(0,7)?'Razão de referência entre meses diferentes; não representa participação apurada no mesmo mês.':'Carteira e mercado com referência no mesmo mês.'} ${info('market')} <button class="text-button" data-go="market">Explorar CAGED e MTE ↗</button></div></div>`+marketPanel(n)}
function marketPanel(n){const m=compatibleMarket(n);if(!m)return '';return `<section class="cards" aria-label="Participação de referência no mercado">${card('Referência CAGED',pct(marketRate(n)),`${fmt(m.caged)} vínculos · ${monthLabel(m.competence)}`,'market')}${card('Participação sobre MTE',pct(m.mte>0?n.metrics.activeContracts/m.mte*100:null),`${fmt(m.mte)} cotas industriais · ${monthLabel(m.competence)}`,'Carteira vigente dividida pelas cotas industriais MTE da referência indicada. Meses diferentes; razão de referência.')}${card('Diferença CAGED / carteira',m.caged>0?fmt(m.caged-n.metrics.activeContracts):'—','Diferença entre referências; não são vagas','Diferença aritmética de estoques em datas distintas. Não equivale a vagas livres nem atendimento confirmado por outras instituições.')}${card('Referência de mercado',monthLabel(m.competence),'CAGED e MTE · últimas bases fornecidas','A competência da carteira é independente da competência de mercado.')}</section>`}
function bars(n,limit=8){let children=[...n.children].sort((a,b)=>b.metrics[state.metric]-a.metrics[state.metric]);const max=Math.max(1,...children.map(c=>c.metrics[state.metric]));return children.length?`<div class="bars">${children.slice(0,limit).map(c=>`<button class="bar-row" data-drill="${esc(c.id)}" data-tip="${esc(c.label)}: ${fmt(c.metrics[state.metric])}. Clique para aprofundar."><span class="bar-label">${esc(c.label)}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${c.metrics[state.metric]/max*100}%"></span></span><span class="bar-number">${fmt(c.metrics[state.metric])}</span><span class="bar-arrow">›</span></button>`).join('')}</div>`:`<div class="empty">Este é o último nível. Use o caminho acima para voltar.</div>`}
function territoryPanel(n){return `<section class="panel"><div class="panel-head"><div><h2>${n.type==='state'?'Onde está nossa carteira':n.type==='region'?'Unidades do território':'Cursos da unidade'}</h2><p class="panel-sub">${metricNames[state.metric]} · clique nas barras para aprofundar</p></div><select class="small-select metric-select" id="metric" aria-label="Indicador do ranking">${Object.entries(metricNames).map(([k,v])=>`<option value="${k}" ${state.metric===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="panel-body">${bars(n)}<div class="chart-foot"><span>${Math.min(8,n.children.length)} de ${n.children.length} ${n.type==='state'?'regiões':n.type==='region'?'unidades':'cursos'}</span><button class="text-button" data-go="regions">Ver detalhamento ↗</button></div></div></section>`}
function coveragePanel(n){const m=n.metrics,p=coverage(n)||0,circ=2*Math.PI*73;return `<section class="panel"><div class="panel-head"><div><h2>Cobertura da carteira ${info('coverage')}</h2><p class="panel-sub">Pessoas com vínculo vigente na data-base</p></div></div><div class="panel-body"><div class="donut-wrap"><svg viewBox="0 0 190 190" role="img" aria-label="${pct(p)} das pessoas possuem vínculo vigente"><circle cx="95" cy="95" r="73" fill="none" stroke="#eaf0f7" stroke-width="21"/><circle cx="95" cy="95" r="73" fill="none" stroke="#1464e9" stroke-width="21" stroke-dasharray="${p/100*circ} ${circ}" stroke-linecap="round"/></svg><div class="donut-center"><strong>${pct(p)}</strong><span>com vínculo vigente</span></div></div><div class="legend"><div class="legend-row"><i class="dot"></i>Com vínculo vigente<strong>${fmt(m.activeStudents)}</strong></div><div class="legend-row"><i class="dot" style="background:#d7e3f1"></i>Sem vínculo vigente<strong>${fmt(m.students-m.activeStudents)}</strong></div></div><div class="mini-note">A cobertura conta pessoas uma única vez. Vínculos e matrículas são apresentados separadamente.</div></div></section>`}
function overview(n){const m=n.metrics;return cards(n)+marketNotice(n)+`<div class="grid-main">${territoryPanel(n)}${coveragePanel(n)}</div><section class="summary-strip" aria-label="Pontos de atenção"><div><span class="label">ACOMPANHAR</span><strong>${fmt(m.exclusiveNoContractStudents)}</strong><span>pessoas com matrícula sem CNPJ e sem vínculo vigente ${info('exclusiveNoContractStudents')}</span></div><div><span class="label">PLANEJAR REPOSIÇÃO</span><strong>${fmt(m.expiring90)}</strong><span>vínculos vigentes terminam em até 90 dias</span></div><div><span class="label">PRÓXIMAS ENTRADAS</span><strong>${fmt(m.futureContracts)}</strong><span>vínculos com início posterior à data-base</span></div></section>`+tablePanel(n)}
function tablePanel(n){const rows=filteredChildren(n);return `<section class="panel section-space"><div class="panel-head"><div><h2>${n.type==='state'?'Leitura regional':n.type==='region'?'Leitura por unidade':'Leitura por curso'}</h2><p class="panel-sub">Totais distintos são recalculados em cada nível; não some pessoas ou empresas entre linhas.</p></div><span class="pill">${n.children.length} ${n.type==='state'?'regiões':n.type==='region'?'unidades':'cursos'}</span></div><div class="table-toolbar"><input id="search" class="search" type="search" placeholder="Buscar ${n.type==='state'?'região':n.type==='region'?'unidade':'curso'}…" aria-label="Buscar no detalhamento" value="${esc(state.query)}"><button class="button secondary" id="exportTable">↓ CSV do recorte</button></div><div class="table-scroll"><table><thead><tr><th><button data-sort="label">${n.type==='state'?'Sub-região':n.type==='region'?'Unidade':'Curso'} ↕</button></th>${[['students','Pessoas'],['activeContracts','Vínculos vigentes'],['companies','Empresas'],['exclusiveNoContractStudents','Sem vínculo¹']].map(([k,v])=>`<th class="num"><button data-sort="${k}">${v} ${state.sort===k?(state.descending?'↓':'↑'):'↕'}</button></th>`).join('')}<th class="num">Cobertura</th><th class="num">Ref. CAGED</th></tr></thead><tbody id="tableBody">${tableRows(rows)}</tbody></table></div><div class="table-footer"><span id="rowCount">${rows.length} resultados</span><span>¹ Matrícula sem CNPJ e sem vínculo vigente</span></div></section>`}
function filteredChildren(n){const term=state.query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();return n.children.filter(c=>c.label.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(term)).sort((a,b)=>{const result=state.sort==='label'?a.label.localeCompare(b.label,'pt-BR'):a.metrics[state.sort]-b.metrics[state.sort];return state.descending?-result:result})}
function tableRows(rows){return rows.length?rows.map(c=>`<tr><td class="name"><button data-drill="${esc(c.id)}">${esc(c.label)} ${c.children.length?'›':'↗'}</button></td><td class="num">${fmt(c.metrics.students)}</td><td class="num">${fmt(c.metrics.activeContracts)}</td><td class="num">${fmt(c.metrics.companies)}</td><td class="num">${fmt(c.metrics.exclusiveNoContractStudents)}</td><td class="num">${pct(coverage(c))}</td><td class="num">${pct(marketRate(c))}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">Nenhum resultado neste recorte.</td></tr>'}
function monthsPanel(n){const months=Object.keys(n.months).sort(),max=Math.max(1,...Object.values(n.months));return `<section class="panel section-space"><div class="panel-head"><div><h2>Agenda de vencimentos ${info('months')}</h2><p class="panel-sub">Clique em um mês para localizar os territórios, unidades ou cursos com maior volume.</p></div><span class="pill">${fmt(n.metrics.activeContracts)} vínculos vigentes</span></div><div class="panel-body"><div class="months">${months.map(m=>`<button class="month ${state.month===m?'selected':''}" data-month="${m}" aria-pressed="${state.month===m}" data-tip="${fmt(n.months[m])} vínculos terminam em ${monthLabel(m)}"><strong>${fmt(n.months[m])}</strong><div class="month-stick" style="height:${Math.max(2,n.months[m]/max*160)}px"></div><span>${monthLabel(m)}</span></button>`).join('')||'<div class="empty">Não há vínculos vigentes neste recorte.</div>'}</div><div class="mini-note">A agenda reflete o que era conhecido em ${date(snapshot().date)}. Encerramentos não são descontados automaticamente de outras fotografias.</div></div></section>`}
function contracts(n){const month=state.month||Object.keys(n.months).sort()[0];if(!state.month)state.month=month;const children=[...n.children].sort((a,b)=>(b.months[month]||0)-(a.months[month]||0));return cards(n)+monthsPanel(n)+`<div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${month?'Vencimentos em '+monthLabel(month):'Vencimentos'}</h2><p class="panel-sub">Distribuição no próximo nível da análise</p></div></div><div class="panel-body"><div class="legend">${children.filter(c=>c.months[month]).map(c=>`<button class="bar-row" data-drill="${esc(c.id)}"><span class="bar-label">${esc(c.label)}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${(c.months[month]||0)/Math.max(1,...children.map(x=>x.months[month]||0))*100}%"></span></span><strong class="bar-number">${fmt(c.months[month])}</strong><span>›</span></button>`).join('')||'<p class="muted">Sem vencimentos detalhados neste nível.</p>'}</div></div></section>${scenario(n)}</div>`}
function scenario(n){const market=compatibleMarket(n),mk=market?.caged>0?market:null;return `<section class="panel"><div class="panel-head"><div><h2>Simular a meta</h2><p class="panel-sub">Uma hipótese de planejamento, não uma previsão.</p></div></div><div class="panel-body">${mk?`<label for="target">Meta de participação: <strong id="targetValue">80%</strong></label><input type="range" id="target" class="slider" min="1" max="100" value="80"><div class="slider-values"><span>1%</span><span>100%</span></div><div class="scenario-result"><div id="scenarioNumber" class="scenario-value"></div><p>vínculos adicionais líquidos necessários</p></div><p class="mini-note">Denominador CAGED fixo em ${fmt(mk.caged)} (${monthLabel(mk.competence)}), comparado à carteira de ${date(snapshot().date)}. Entradas brutas devem ainda compensar encerramentos. Sem pressupor conversão automática das pendências.</p>`:`<div class="empty"><strong>Falta o denominador compatível</strong>Quando o estoque CAGED deste período e território for fornecido, a simulação de meta ficará disponível.</div>`}</div></section>`}
function historyView(){return `<section class="panel section-space"><div class="panel-head"><div><h2>Fotografias disponíveis</h2><p class="panel-sub">Cada leitura guarda seus próprios filtros, vínculos e denominadores.</p></div><span class="pill">${snapshots.length} ${snapshots.length===1?'base':'bases'}</span></div><div class="table-scroll"><table><thead><tr><th>Data da base</th><th class="num">Pessoas</th><th class="num">Vínculos vigentes</th><th class="num">Empresas</th><th class="num">Ref. CAGED</th><th>Base de mercado</th></tr></thead><tbody>${snapshots.map(s=>{const n=s.slices[state.modality],mk=state.modality==='all'&&n.market;return `<tr><td><button class="text-button" data-period="${s.date}">${date(s.date)} →</button></td><td class="num">${fmt(n.metrics.students)}</td><td class="num">${fmt(n.metrics.activeContracts)}</td><td class="num">${fmt(n.metrics.companies)}</td><td class="num">${mk?.caged&&(mk.competence===s.date.slice(0,7)||mk.referenceMode==='latest_available')?pct(n.metrics.activeContracts/mk.caged*100):'—'}</td><td><span class="pill ${mk?'green':'amber'}">${mk?monthLabel(mk.competence):'Pendente'}</span></td></tr>`}).join('')}</tbody></table></div><div class="panel-body">${snapshots.length<2?'<div class="empty"><strong>A série começa em '+date(snapshot().date)+'</strong>A comparação será habilitada quando uma segunda base for adicionada. Não há períodos ou resultados simulados.</div>':compareSnapshots()}</div></section><div class="notice"><span class="symbol">↗</span><div>Para acrescentar uma nova leitura, processe a nova base com sua data correspondente. As datas anteriores permanecem disponíveis no seletor, sem substituir o histórico.</div></div>`}
function compareSnapshots(){const curr=snapshot(),idx=snapshots.indexOf(curr),prev=snapshots[idx-1];if(!prev)return '<p class="muted">Esta é a primeira fotografia da série.</p>';const a=curr.slices[state.modality].metrics,b=prev.slices[state.modality].metrics;return `<h3 style="margin-top:24px">Variação desde ${date(prev.date)}</h3><div class="cards" style="margin-top:16px">${['students','activeContracts','companies'].map(k=>card(metricNames[k],(a[k]-b[k]>0?'+':'')+fmt(a[k]-b[k]),'Diferença entre fotografias',k)).join('')}</div><p class="mini-note">A diferença de estoques não identifica, sozinha, admissões, desligamentos ou retenção das mesmas pessoas.</p>`}
function quality(){const s=snapshot(),q=s.quality;return `<div class="notice"><span class="symbol">◎</span><div><strong>Regras explícitas, números rastreáveis.</strong> O dashboard publica somente agregados. Pessoas, contatos e identificadores individuais não fazem parte dos arquivos do site.</div></div><div class="quality-grid"><section class="panel"><div class="panel-head"><h2>Como calculamos</h2></div><ul class="method-list"><li><strong>Data de leitura</strong><p>${date(s.date)}. Fotografia da base fornecida; não representa automaticamente um trimestre acumulado.</p></li><li><strong>Pessoas e matrículas</strong><p>Somente cursos de Aprendizagem Industrial com status Matriculado. Pessoa distinta por CPF, com RA como alternativa. Matrículas mantidas em indicador separado.</p></li><li><strong>Vínculo vigente</strong><span class="formula">Início ≤ data-base ≤ término · CNPJ válido</span><p>Deduplicado por pessoa, CNPJ, início e término. Sem número de contrato padronizado, esta é uma chave operacional; não substitui auditoria documental.</p></li><li><strong>Empresas ativas</strong><p>CNPJs distintos associados a vínculos vigentes. Exclui ausentes, zero e CNPJs inconsistentes. Totais regionais não são aditivos.</p></li><li><strong>Market share</strong><span class="formula">Vínculos da carteira ÷ estoque CAGED da referência × 100</span><p>A carteira de setembro usa explicitamente as últimas bases fornecidas, de julho de 2026. Meses diferentes geram uma razão de referência, não participação contemporânea. Filtros de modalidade e níveis sem denominador ficam sem resultado. MTE é uma referência distinta, sem pressupor que seja maior que CAGED em todo território.</p></li><li><strong>Concentração</strong><p>Média de vínculos por empresa não determina risco. O detalhamento informa participação da maior empresa e das cinco maiores, sem expor seus identificadores.</p></li></ul></section><section class="panel"><div class="panel-head"><h2>Conferência da base</h2><span class="pill">${date(s.date)}</span></div><ul class="method-list"><li><strong>${fmt(s.sourceRows)} registros na origem</strong><p>${fmt(s.learningRows)} registros de Aprendizagem Industrial; ${fmt(s.slices.all.metrics.records)} registros Matriculados no recorte.</p></li><li><strong>${fmt(q.extraPersonRows)} matrículas além da contagem de pessoas</strong><p>Várias matrículas da mesma pessoa são permitidas e não aumentam a contagem de pessoas.</p></li><li><strong>${fmt(q.invalidCnpjRows)} registros com CNPJ inconsistente</strong><p>Excluídos dos vínculos vigentes até conferência. Não são convertidos automaticamente em pessoas para formalizar.</p></li><li><strong>${fmt(q.invalidDateRows)} registros com datas ausentes ou inconsistentes</strong><p>Não tratados como vínculos vigentes sem confirmação.</p></li><li><strong>${fmt(q.futureContracts)} vínculos futuros · ${fmt(q.expiredContracts)} encerrados</strong><p>Separados da carteira vigente usando as datas da base.</p></li><li><strong>${fmt(q.unmappedRows)} registros sem região mapeada</strong><p>Mapeamento por código da filial proveniente da base regional de julho de 2026. Novos códigos ficam explicitamente sem mapeamento; revisar reorganizações territoriais.</p></li><li><strong>Origem</strong><p>${esc(s.source)} · ${esc(s.sheet)}. CAGED/MTE: ${s.slices.all.market?'competência '+esc(s.slices.all.market.competence):'aguardando base correspondente'}.</p></li></ul></section></div>`}
function breadcrumbs(){let n=root();const parts=[`<button data-up="0">Rio Grande do Sul</button>`];state.path.forEach((id,i)=>{n=n.children.find(c=>c.id===id)||n;parts.push(`<span>›</span><button data-up="${i+1}" class="${i===state.path.length-1?'current':''}">${esc(n.label)}</button>`)});$('#breadcrumbs').innerHTML=parts.join('')+(state.path.length?'<button class="text-button" id="drillUp" style="margin-left:auto">↑ Voltar um nível</button>':'<span class="current">/ visão estadual</span>')}
function render(){if(!snapshots.length){$('#content').innerHTML='<div class="empty"><strong>Base não carregada</strong>Verifique a disponibilidade do arquivo de dados e recarregue a página.</div>';return}const n=node();breadcrumbs();$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#pageTitle').textContent=({overview:'Aprendizagem em perspectiva',regions:'Do território à sala de aula',contracts:'Antecipe os próximos vencimentos',history:'Uma fotografia de cada período',market:'O mercado, município a município',quality:'Confiança começa na definição'})[state.view];$('#pageSubtitle').textContent=state.view==='overview'?'A carteira de hoje. As decisões para o próximo período.':state.view==='regions'?'Explore as regiões, aprofunde nas unidades e chegue aos cursos.':state.view==='contracts'?'Planeje a reposição a partir dos términos previstos.':state.view==='market'?'CAGED e potencial MTE · referências preservadas por fotografia · RS.':state.view==='history'?'Compare períodos com regras consistentes, sem sobrescrever o passado.':'Consulte o recorte, as fórmulas e as pendências de conferência.';$('#content').innerHTML=state.view==='overview'?overview(n):state.view==='regions'?cards(n)+marketNotice(n)+tablePanel(n):state.view==='contracts'?contracts(n):state.view==='history'?historyView():state.view==='market'?marketView():quality();$('#source').textContent=`Fonte: ${snapshot().source} · Leitura ${date(snapshot().date)}`;$('#period').value=state.period;$('#modality').value=state.modality;updateScenario();writeHash()}
function writeHash(){const params=new URLSearchParams({data:state.period,visao:state.view,modalidade:state.modality});if(state.path.length)params.set('caminho',state.path.join('/'));try{window.history.replaceState(null,'','#'+params)}catch{}}
function detail(c){$('#dialogTitle').textContent=c.label;const m=c.metrics;$('#dialogBody').innerHTML=`<p class="muted">${date(snapshot().date)} · ${esc(c.type==='course'?'Curso':'Recorte')}</p><div class="dialog-metrics">${[['Pessoas matriculadas',fmt(m.students)],['Vínculos vigentes',fmt(m.activeContracts)],['Empresas distintas',fmt(m.companies)],['Sem vínculo vigente¹',fmt(m.exclusiveNoContractStudents)],['Maior empresa / vínculos',pct(m.top1Share)],['Cinco maiores / vínculos',pct(m.top5Share)]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><p class="mini-note">¹ Pessoas com matrícula sem CNPJ e sem vínculo vigente identificado no recorte. ${fmt(m.futureContracts)} vínculos futuros e ${fmt(m.expiredContracts)} encerrados estão fora da contagem de vigentes. As participações empresariais medem distribuição, sem classificação automática de risco.</p>`;$('#detailDialog').showModal()}
function drill(id){const c=node().children.find(x=>x.id===id);if(!c)return;if(!c.children.length){detail(c);return}state.path.push(id);state.query='';render()}
function updateScenario(){const range=$('#target'),mk=compatibleMarket(node());if(!range||!mk||!(mk.caged>0))return;$('#targetValue').textContent=range.value+'%';$('#scenarioNumber').textContent=fmt(Math.max(0,Math.ceil(mk.caged*Number(range.value)/100)-node().metrics.activeContracts))}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}
function exportCSV(table=false){const n=node(),rows=table?filteredChildren(n):[n,...filteredChildren(n)];const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const head=['Data da base','Referencia CAGED','Recorte','Pessoas distintas','Registros matricula','Vinculos vigentes','Empresas distintas','Pessoas sem CNPJ e sem vinculo vigente','Cobertura contratual (%)','Razão CAGED de referência (%)'];const lines=rows.map(r=>[snapshot().date,compatibleMarket(r)?.competence??'',r.label,r.metrics.students,r.metrics.records,r.metrics.activeContracts,r.metrics.companies,r.metrics.exclusiveNoContractStudents,coverage(r)?.toFixed(4)??'',marketRate(r)?.toFixed(4)??'']);const blob=new Blob(['\ufeff'+[head,...lines].map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`aprendizagem-${snapshot().date}-${state.modality}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Leitura agregada exportada. Os filtros selecionados foram respeitados.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view||b.dataset.go){state.view=b.dataset.view||b.dataset.go;state.query='';render()}else if(b.dataset.city)cityDetail(b.dataset.city);else if(b.dataset.marketSort){state.marketDescending=state.marketSort===b.dataset.marketSort?!state.marketDescending:true;state.marketSort=b.dataset.marketSort;render()}else if(b.id==='exportMarket')exportMarket();else if(b.dataset.drill)drill(b.dataset.drill);else if(b.dataset.up!==undefined){state.path=state.path.slice(0,Number(b.dataset.up));state.query='';render()}else if(b.id==='drillUp'){state.path.pop();state.query='';render()}else if(b.dataset.sort){state.descending=state.sort===b.dataset.sort?!state.descending:true;state.sort=b.dataset.sort;render()}else if(b.dataset.month){state.month=b.dataset.month;render()}else if(b.dataset.period){state.period=b.dataset.period;state.path=[];state.view='overview';render()}else if(b.id==='reset'){state.modality='all';state.path=[];state.query='';state.month=null;state.marketRule='all';state.marketQuery='';render()}else if(b.id==='export'||b.id==='exportTable'){if(state.view==='market')exportMarket();else exportCSV(b.id==='exportTable')}else if(b.id==='methodLink'){state.view='quality';render()}else if(b.id==='closeDialog')$('#detailDialog').close()});
document.addEventListener('change',e=>{if(e.target.id==='marketRule'){state.marketRule=e.target.value;render()}if(e.target.id==='period'){state.period=e.target.value;state.path=[];state.query='';state.month=null;render()}if(e.target.id==='modality'){state.modality=e.target.value;state.path=[];state.query='';state.month=null;render()}if(e.target.id==='metric'){state.metric=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='marketSearch'){state.marketQuery=e.target.value;$('#marketRows').innerHTML=marketRows();$('#marketCount').textContent=marketFiltered().length+' municípios'}if(e.target.id==='search'){state.query=e.target.value;const rows=filteredChildren(node());$('#tableBody').innerHTML=tableRows(rows);$('#rowCount').textContent=rows.length+' resultados'}if(e.target.id==='target')updateScenario()});
function showTip(el){if(!el?.dataset.tip)return;const tip=$('#tooltip');tip.textContent=el.dataset.tip;tip.hidden=false;const r=el.getBoundingClientRect(),w=tip.offsetWidth;tip.style.left=Math.max(8,Math.min(r.left,innerWidth-w-8))+'px';tip.style.top=Math.max(8,Math.min(r.bottom+8,innerHeight-tip.offsetHeight-8))+'px'}
document.addEventListener('mouseover',e=>showTip(e.target.closest('[data-tip]')));document.addEventListener('focusin',e=>showTip(e.target.closest('[data-tip]')));document.addEventListener('mouseout',e=>{if(e.target.closest('[data-tip]'))$('#tooltip').hidden=true});document.addEventListener('focusout',()=>$('#tooltip').hidden=true);window.addEventListener('scroll',()=>$('#tooltip').hidden=true,true);document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#tooltip').hidden=true;if(e.altKey&&e.key==='ArrowUp'&&state.path.length){e.preventDefault();state.path.pop();state.query='';render()}});

function marketFiltered(){const q=state.marketQuery.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();return (snapshot().marketGeography||[]).filter(r=>(state.marketRule==='all'||r.rule===state.marketRule)&&r.name.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q)).sort((a,b)=>{let x=state.marketSort==='name'?a.name.localeCompare(b.name,'pt-BR'):a[state.marketSort]-b[state.marketSort];return state.marketDescending?-x:x})}
function marketRows(){return marketFiltered().map(r=>`<tr><td class="name"><button data-city="${esc(r.name)}">${esc(r.name)} ↗</button></td><td><span class="pill ${r.rule==='EAD'?'green':'amber'}">Regra ${r.rule}</span></td><td class="num">${fmt(r.potential)}</td><td class="num">${fmt(r.industry)}</td><td class="num">${fmt(r.caged)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum município neste filtro.</td></tr>'}
function marketView(){const s=snapshot(),rows=s.marketGeography||[],audit=s.marketAudit;if(!rows.length)return '<div class="empty">Base municipal ainda não disponível para esta fotografia.</div>';const ead=rows.filter(r=>r.rule==='EAD'),pres=rows.filter(r=>r.rule==='Presencial');return `<div class="notice"><span class="symbol">◎</span><div><strong>Mercado municipal do RS · ${monthLabel(s.marketSources.mteCompetence)}.</strong> Os filtros de modalidade e unidade da carteira não alteram esta base municipal. O potencial total define a regra; somente as cotas da coluna Indústria compõem o potencial industrial.</div></div><section class="cards">${card('Cotas industriais MTE',fmt(rows.reduce((a,r)=>a+r.industry,0)),`${rows.length} municípios · ${monthLabel(s.marketSources.mteCompetence)}`,'Soma da coluna Indústria com UF RS, sem somar outros setores.')}${card('Regra EAD',fmt(ead.length),`${fmt(ead.reduce((a,r)=>a+r.industry,0))} cotas industriais`,'Municípios com Potencial da Cota total menor ou igual a 100; inclui 100 e zero.')}${card('Regra Presencial',fmt(pres.length),`${fmt(pres.reduce((a,r)=>a+r.industry,0))} cotas industriais`,'Municípios com Potencial da Cota total maior que 100.')}${card('Estoque CAGED estadual',fmt(audit.reportedCaged),`Total das capturas · ${monthLabel(s.marketSources.cagedCompetence)}`,'O denominador estadual utiliza o total declarado na captura, não a soma municipal ainda em conferência.')}</section><div class="notice"><span class="symbol">!</span><div><strong>Conferência CAGED municipal:</strong> soma extraída ${fmt(audit.municipalCaged)} × total exibido ${fmt(audit.reportedCaged)}: diferença de ${fmt(audit.difference)} vínculos. Detalhamento municipal provisório; nenhuma correção automática foi aplicada. Admissões: ${fmt(audit.admissions)} · desligamentos: ${fmt(audit.dismissals)} · saldo: +${fmt(audit.balance)}.</div></div><section class="panel"><div class="panel-head"><div><h2>Potencial e regra de oferta</h2><p class="panel-sub">Busque, filtre, ordene e clique no município para conhecer a regra aplicada.</p></div><button id="exportMarket" class="button secondary">↓ CSV municipal</button></div><div class="table-toolbar"><input id="marketSearch" class="search" type="search" aria-label="Buscar município" placeholder="Buscar município…" value="${esc(state.marketQuery)}"><label>Regra <select id="marketRule" class="small-select">${['all','EAD','Presencial'].map(k=>`<option value="${k}" ${state.marketRule===k?'selected':''}>${k==='all'?'Todas':k}</option>`).join('')}</select></label></div><div class="table-scroll"><table><thead><tr><th><button data-market-sort="name">Município ↕</button></th><th>Regra</th>${[['potential','Potencial total¹'],['industry','Cotas industriais'],['caged','Estoque CAGED²']].map(([k,v])=>`<th class="num"><button data-market-sort="${k}">${v} ↕</button></th>`).join('')}</tr></thead><tbody id="marketRows">${marketRows()}</tbody></table></div><div class="table-footer"><span id="marketCount">${marketFiltered().length} municípios</span><span>¹ Critério EAD/Presencial · ² Em conferência</span></div></section><p class="mini-note">Fonte: <a href="${esc(s.marketSources.mte)}" target="_blank" rel="noopener">MTE — potencial de ${monthLabel(s.marketSources.mteCompetence)}</a>; CAGED: 20 capturas fornecidas. A classificação aplica o critério solicitado e não determina a modalidade efetivamente ofertada. Não há razão SENAI municipal sem município validado da empresa contratante.</p>`}
function cityDetail(name){const r=snapshot().marketGeography.find(x=>x.name===name);if(!r)return;$('#dialogTitle').textContent=r.name;$('#dialogBody').innerHTML=`<p class="muted">Rio Grande do Sul · mercado de ${monthLabel(snapshot().marketSources.mteCompetence)}</p><div class="dialog-metrics"><div><span>Potencial total da cota</span><strong>${fmt(r.potential)}</strong></div><div><span>Potencial industrial</span><strong>${fmt(r.industry)}</strong></div><div><span>Estoque CAGED · provisório</span><strong>${fmt(r.caged)}</strong></div><div><span>Classificação</span><strong>Regra ${r.rule}</strong></div></div><p class="mini-note">${fmt(r.potential)} ${r.potential<=100?'≤ 100: Regra EAD.':'> 100: Regra Presencial.'} A classificação considera o potencial total municipal; o indicador industrial utiliza exclusivamente a coluna Indústria. O CAGED municipal permanece em conferência (diferença estadual de ${fmt(snapshot().marketAudit.difference)} vínculos).</p>`;$('#detailDialog').showModal()}
function exportMarket(){const rows=marketFiltered(),s=snapshot();const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const lines=[['Data carteira','Referencia mercado','Municipio','Regra','Potencial total','Cotas industria','CAGED municipal provisorio','Conferencia CAGED'],...rows.map(r=>[s.date,s.marketSources.mteCompetence,r.name,r.rule,r.potential,r.industry,r.caged,`Soma municipal difere ${s.marketAudit.difference} do total estadual informado`])];const blob=new Blob(['\ufeff'+lines.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mercado-RS-'+s.marketSources.mteCompetence+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Base municipal exportada com os filtros e a nota de conferência.')}

if(snapshots.length){state.period=snapshots.at(-1).date;const params=new URLSearchParams(location.hash.slice(1));if(snapshots.some(s=>s.date===params.get('data')))state.period=params.get('data');if(['overview','regions','contracts','history','market','quality'].includes(params.get('visao')))state.view=params.get('visao');if(['all','basic','technical'].includes(params.get('modalidade')))state.modality=params.get('modalidade');let r=root();for(const id of (params.get('caminho')||'').split('/').filter(Boolean)){const c=r.children.find(x=>x.id===id);if(!c||!c.children.length)break;state.path.push(id);r=c}$('#period').innerHTML=snapshots.map(s=>`<option value="${s.date}">${date(s.date)}</option>`).join('')}render();

